{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C58"],
      "claim": "Fluvastatin, the closest structural analogue (Morgan 0.5362), has an absolute oral bioavailability of 0.29 in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Cerivastatin, a close statin analogue sharing the dihydroxyheptenoic acid and 4-fluorophenyl motif, has an absolute oral bioavailability of 60% (90% CI 51-70%) in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Rosuvastatin, another close statin analogue, has an absolute oral bioavailability of 20% in humans, meeting the F >= 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "One fluvastatin study reported 19% oral bioavailability after a 10 mg dose, just below the threshold, indicating borderline first-pass extraction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a statin-like dihydroxyheptenoic acid with a 4-fluorophenyl heterocycle. The closest analogues—fluvastatin, cerivastatin, and rosuvastatin—all show human absolute oral bioavailability at or above 20% (29%, 60%, and 20%, respectively). Although one fluvastatin study reported 19%, the weight of direct statin evidence supports F >= 20%. Physicochemical ionization concerns are outweighed by experimental statin bioavailability data.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the exact cyclopropyl-quinoline analogue.",
    "Fluvastatin's bioavailability is borderline near the 20% threshold, adding uncertainty.",
    "Potential differences in first-pass metabolism or transporter-mediated disposition due to the quinoline/cyclopropyl substitution are unquantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

